mapper.select:
SELECT COUNT(*)
FROM hdoc_user_infor
WHERE USERID = #{userid}

SELECT
    u.USERID AS userid,
    u.USERNAME AS `user`,
    GROUP_CONCAT(DISTINCT m.MARKET ORDER BY m.MARKET SEPARATOR ',') AS market
FROM hdoc_user_infor u
INNER JOIN HDOC_MARKET_AUTH m ON u.USERID = m.USERID

INNER JOIN HDOC_FUNCTION_AUTH f ON u.USERID = f.USERID



        u.USERID = #{userid}


        AND u.USERNAME = #{username}


        AND f.`FUNCTION` = #{functionCode}


        AND m.MARKET = #{market}


GROUP BY u.USERID, u.USERNAME

SELECT DOCTYPE AS doctype, DESCRIPTION AS description, REGISTER_USER AS registerUser, REGISTER_DATETIME AS registerDatetime FROM HDOC_DOCUMENT_LIST
DOCTYPE = #{documentType}
DOCTYPE != #{documentType}
